class K {                                    // every instance has the same hash
    final int i;
    K(int i) { this.i = i; }
    @Override public int hashCode() { return 1; }
    @Override public boolean equals(Object o) { return o instanceof K k && k.i == i; }
}

Map<K, Integer> m = new HashMap<>();         // table of 16 buckets
for (int i = 0; i < 8; i++) m.put(new K(i), i);

